import runpy, numpy as np, math
from collections import defaultdict
D=runpy.run_path('/tmp/build.py')
coords=D['coords'].copy(); atoms=D['atoms']; groups=D['groups']
# remove any preexisting candidate file output replaced later
inds={g:[i for i,x in enumerate(groups) if x==g] for g in set(groups)}
radius={'C':1.70,'H':1.20,'N':1.55,'P':1.80,'Zn':1.39,'Ir':1.80}
# We use soft vdW overlap penalties between different components; Ir is the fixed metal center.
allgroups=['NHC-top','NHC-bottom','PMe3','ZnEt','Ir-hydride']
pairs=[]
for ia,g1 in enumerate(allgroups):
 for g2 in allgroups[ia+1:]:
  for i in inds[g1]:
   for j in inds[g2]:
    ri,rj=atoms[i],atoms[j]
    thresh=0.92*(radius[ri]+radius[rj])
    # intended axial Ir-C bonds aren't in intergroup pairs; only non-Ir components are considered.
    pairs.append((i,j,thresh))

def calc(a,b):
 c=coords.copy()
 for group,ang in [('NHC-top',a),('NHC-bottom',b)]:
  rad=math.radians(ang); R=np.array([[math.cos(rad),-math.sin(rad),0],[math.sin(rad),math.cos(rad),0],[0,0,1.]])
  ix=inds[group]
  c[ix]=c[ix]@R.T
 score=0; mn=10
 for i,j,t in pairs:
  d=np.linalg.norm(c[i]-c[j]); mn=min(mn,d)
  if d<t: score+=(t-d)**2
 return score,mn,c
best=None
for a in range(0,360,5):
 for b in range(0,360,5):
  s,mn,c=calc(a,b)
  if best is None or s<best[0]: best=(s,mn,a,b,c)
print('best score, min, angles',best[:4])
coords=best[4]
with open('answer.xyz','w') as f:
 f.write(f"{len(atoms)}\n")
 f.write('Proposed 3D structure of the depicted Ir/NHC/PMe3/ZnEt complex; Cartesian coordinates in angstrom\n')
 for el,p in zip(atoms,coords): f.write(f'{el:2s} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
# Print problematic pair contacts after rotation
contacts=[]
for i,j,t in pairs:
 d=np.linalg.norm(coords[i]-coords[j])
 if d<2.7: contacts.append((d,t,i,j,atoms[i],atoms[j],groups[i],groups[j]))
print('contacts<2.7', sorted(contacts)[:20])
